import { ConfigValueRecord, ParameterSpecRecord } from "#base/scripts/voronoi-types.js";

import { RegionCell } from "../voronoi-utils.js";
import { Rule, ScoringContext } from "../voronoi_rules/rules-base.js";
interface LatitudeBounds {
	min: number;
	max: number;
	center: number;
	weight: number;
	index: number;
}

interface LatitudeSetting extends ConfigValueRecord {
	latitude: number;
	weight: number;
}

class LatitudeCells {
	totalCells = 0;
	cellsPerLatitude: number[];
	constructor(numLatitudes: number) {
		this.cellsPerLatitude = new Array(numLatitudes).fill(0);
	}
}

const ruleSchema = {
	overlap: {
		label: "Overlap %",
		description: "The amount of overlap allowed between latitudes",
		default: 2,
		min: 0,
		max: 10,
		step: 0.1,
	},
	mirror: {
		label: "Mirror",
		description: "Should the preferred latitudes be mirrored across the equator",
		default: true,
		min: 0,
		max: 1,
		step: 1,
	},
	latitudes: {
		label: "Latitudes",
		description: "latitude bands from -90 to +90 degrees",
		children: {
			latitude: {
				label: "Latitude",
				description: "A latitude bands between -90 and +90 degrees",
				default: 0,
			},
			weight: {
				label: "Weight %",
				description: "What percentage of this continent should be in this latitude band",
				default: 0,
				min: 0,
				max: 100,
				step: 1,
			},
		},
	},
} as const satisfies ParameterSpecRecord;

export class RulePreferLatitude extends Rule {
	override parameterSpecs = ruleSchema;
	override configValues = Rule.createDefaultsFromSpecs(ruleSchema);
	override name = RulePreferLatitude.getName();
	override description =
		"This rule scores cells based on how much area a given region occupies at different latitudes. When it is lacking certain latitudes, then it scores cells in that are higher. When it already has plenty of cells in a latitude, those cells will be scored lower. ";

	private m_latitudeBounds: LatitudeBounds[] = [];
	private m_regionLatitudeCells: Map<number, LatitudeCells> = new Map<number, LatitudeCells>();

	static getName(): string {
		return "Prefer Latitude";
	}

	static getSchema() {
		return ruleSchema;
	}

	prepare() {
		super.prepare();

		this.m_latitudeBounds = [];
		this.m_regionLatitudeCells.clear();

		// build latitude array that takes settings into account.
		let previousBoundary = 0;
		const overlap = this.configValues.overlap * 0.01;
		const halfOverlap = overlap * 0.5;

		// no idea what order things are in, so track indices so we can assign tiles to the buckets in m_regionLatitudeCells. When mirrored,
		// we want each of the the mirrored bands in the same bucket as the non-mirrored bands.
		let latitudes: [number, LatitudeSetting][] = this.configValues.latitudes.map((value, index) => [index, value]);
		if (this.configValues.mirror) {
			latitudes = latitudes.concat(
				latitudes.map((value) => {
					return [value[0], { latitude: -value[1].latitude, weight: value[1].weight }];
				}),
			);
		}

		// reverse order sort since the latitudes are negated below
		latitudes.sort((a, b) => b[1].latitude - a[1].latitude);

		for (let i = 0; i < latitudes.length; ++i) {
			const latitudeDegrees: number = latitudes[i][1].latitude; // -90 to +90
			const latitude = -latitudeDegrees / 180 + 0.5; // 0 to 1
			const last: boolean = i === latitudes.length - 1;
			const nextBoundary = (() => {
				if (last) {
					return 1;
				} else {
					const nextLatitudeDegrees = latitudes[i + 1][1].latitude;
					const nextLatitude = -nextLatitudeDegrees / 180 + 0.5;
					const difference = nextLatitude - latitude;
					return latitude + 0.5 * difference;
				}
			})();
			const latitudeSetting: LatitudeBounds = {
				min: Math.max(0, previousBoundary - halfOverlap),
				max: Math.min(1, nextBoundary + halfOverlap),
				center: latitude,
				weight: latitudes[i][1].weight * 0.01,
				index: latitudes[i][0],
			};
			this.m_latitudeBounds.push(latitudeSetting);
			previousBoundary = nextBoundary;
		}
	}

	score(regionCell: RegionCell, ctx: ScoringContext): number {
		let latitudeCells: LatitudeCells | undefined = this.m_regionLatitudeCells.get(ctx.region.id);
		if (!latitudeCells) {
			latitudeCells = new LatitudeCells(this.configValues.latitudes.length);
			this.m_regionLatitudeCells.set(regionCell.landmassId, latitudeCells);
		}
		const overlap = this.configValues.overlap * 0.01;

		const yPos: number = regionCell.cell.site.y / ctx.m_worldDims.y;
		let score = 0;
		for (let i = 0; i < this.m_latitudeBounds.length; ++i) {
			const bounds = this.m_latitudeBounds[i];
			if (yPos < bounds.min || yPos > bounds.max) continue;
			const weight =
				yPos < bounds.min + overlap
					? (yPos - bounds.min) / overlap
					: yPos > bounds.max - overlap
						? (bounds.max - yPos) / overlap
						: 1;
			const currentPercentage =
				(latitudeCells.cellsPerLatitude[bounds.index] ?? 0) / Math.max(latitudeCells.totalCells, 1);
			const desiredPercentage = bounds.weight;

			score += weight * Math.min(1, Math.max(0, (desiredPercentage - currentPercentage) / desiredPercentage));
		}

		return score;
	}

	public notifySelectedCell(cell: RegionCell, ctx: ScoringContext): void {
		super.notifySelectedCell(cell, ctx);

		let latitudeCells: LatitudeCells | undefined = this.m_regionLatitudeCells.get(cell.landmassId);
		if (!latitudeCells) {
			latitudeCells = new LatitudeCells(this.configValues.latitudes.length);
			this.m_regionLatitudeCells.set(cell.landmassId, latitudeCells);
		}
		latitudeCells.totalCells++;

		const overlap = this.configValues.overlap * 0.01;
		const yPos: number = cell.cell.site.y / ctx.m_worldDims.y;

		for (let i = 0; i < this.m_latitudeBounds.length; ++i) {
			const bounds = this.m_latitudeBounds[i];
			if (yPos < bounds.min) break;
			if (yPos < bounds.min + overlap) {
				latitudeCells.cellsPerLatitude[bounds.index] += (yPos - bounds.min) / overlap;
			} else if (yPos < bounds.max - overlap) {
				latitudeCells.cellsPerLatitude[bounds.index] += 1;
			} else if (yPos < bounds.max) {
				latitudeCells.cellsPerLatitude[bounds.index] += (bounds.max - yPos) / overlap;
			}
		}
	}
}
